/* ---------- 3. עזרים ---------- */
const DAY = 86400000;
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const pick = (r, arr) => arr[Math.floor(r() * arr.length)];
const rint = (r, a, b) => a + Math.floor(r() * (b - a + 1));
const uid = (p) => p + "_" + Math.random().toString(36).slice(2, 9);

const HE_MON = ["ינו'", "פבר'", "מרץ", "אפר'", "מאי", "יוני", "יולי", "אוג'", "ספט'", "אוק'", "נוב'", "דצמ'"];
const HE_DAY = ["ראשון", "שני", "שלישי", "רביעי", "חמישי", "שישי", "שבת"];
const toISO = (d) => new Date(d).toISOString().slice(0, 10);
const startOfDay = (d) => { const x = new Date(d); x.setHours(0, 0, 0, 0); return x.getTime(); };
const fmtD = (s) => { const d = new Date(s); return `${d.getDate()} ${HE_MON[d.getMonth()]}`; };
const fmtDY = (s) => { const d = new Date(s); return `${d.getDate()} ${HE_MON[d.getMonth()]} ${d.getFullYear()}`; };
const daysAgo = (s) => Math.floor((startOfDay(Date.now()) - startOfDay(s)) / DAY);
function relText(s) {
  if (!s) return "לא תועד קשר קודם";
  const n = daysAgo(s);
  if (n < 0) return `בעוד ${Math.abs(n)} ימים`;
  if (n === 0) return "היום";
  if (n === 1) return "אתמול";
  if (n < 7) return `לפני ${n} ימים`;
  if (n < 31) return `לפני ${Math.round(n / 7)} שב׳`;
  if (n < 365) return `לפני ${Math.round(n / 30)} חוד׳`;
  return `לפני ${(n / 365).toFixed(1)} שנים`;
}
const nis = (v) => "₪" + Math.round(v).toLocaleString("en-US");
const kNis = (v) => (v >= 1000000 ? "₪" + (v / 1000000).toFixed(1) + "M" : v >= 1000 ? "₪" + Math.round(v / 1000) + "K" : nis(v));
function waLink(phone) {
  const d = String(phone || "").replace(/\D/g, "");
  return "https://wa.me/" + (d.startsWith("0") ? "972" + d.slice(1) : d);
}

