const projXY = (lat, lng) => [
  ((lng - MAP.lng0) / (MAP.lng1 - MAP.lng0)) * MAP.w,
  ((MAP.lat1 - lat) / (MAP.lat1 - MAP.lat0)) * MAP.h,
];

/* מיקום הלקוח: לפי היישוב, ואם אינו מזוהה — מרכז האזור */
function geoOf(c) {
  const g = GEO[c.place];
  if (g) return { lat: g[0], lng: g[1], exact: true };
  const r = REGION_GEO[c.regionId];
  return r ? { lat: r[0], lng: r[1], exact: false } : null;
}

/* מרחק אווירי בקילומטרים */
function kmBetween(a, b) {
  const R = 6371, rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad, dLng = (b.lng - a.lng) * rad;
  const s1 = Math.sin(dLat / 2), s2 = Math.sin(dLng / 2);
  const h = s1 * s1 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * s2 * s2;
  return Math.round(2 * R * Math.asin(Math.min(1, Math.sqrt(h))));
}

/* השכנים הקרובים ביותר ללקוח */
function nearestTo(customer, customers, n = 5) {
  const from = geoOf(customer);
  if (!from) return [];
  return customers
    .filter((c) => c.id !== customer.id)
    .map((c) => { const g = geoOf(c); return g ? { c, km: kmBetween(from, g), exact: g.exact } : null; })
    .filter(Boolean)
    .sort((a, b) => a.km - b.km)
    .slice(0, n);
}

