/* ---------- 9. אלמנט חתימה: מד לחץ מגע ---------- */
/* קשת בסגנון מנומטר: ככל שעבר יותר זמן מהמגע האחרון — המחוג יורד ללחץ נמוך */
function PressureGauge({ days, size = 54, thick = 4, showLabel = true }) {
  const cap = 30;
  const pressure = Math.max(0, Math.min(1, 1 - (days == null ? cap : Math.min(days, cap)) / cap));
  const c = pressure > 0.62 ? T.drip : pressure > 0.33 ? T.brass : T.rust;
  const R = (size - thick) / 2 - 1;
  const cx = size / 2, cy = size / 2 + 3;
  const A0 = Math.PI * 0.88, A1 = Math.PI * 0.12; // קשת עליונה מימין לשמאל
  const ang = A0 + (A1 - A0) * pressure;
  const pt = (a) => [cx + R * Math.cos(a), cy - R * Math.sin(a)];
  const [x0, y0] = pt(A0), [x1, y1] = pt(A1), [xn, yn] = pt(ang);
  return (
    <div style={{ position: "relative", width: size, height: size * 0.78 }}>
      <svg width={size} height={size * 0.78} viewBox={`0 0 ${size} ${size * 0.78}`}>
        <path d={`M${x0} ${y0} A${R} ${R} 0 0 1 ${x1} ${y1}`} fill="none" stroke={T.line} strokeWidth={thick} strokeLinecap="round" />
        <path d={`M${x0} ${y0} A${R} ${R} 0 0 1 ${xn} ${yn}`} fill="none" stroke={c} strokeWidth={thick} strokeLinecap="round" />
        <line x1={cx} y1={cy} x2={xn} y2={yn} stroke={c} strokeWidth={1.6} strokeLinecap="round" opacity=".85" />
        <circle cx={cx} cy={cy} r={2.4} fill={c} />
      </svg>
      {showLabel && (
        <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "flex-end", justifyContent: "center", pointerEvents: "none" }}>
          <span style={{ fontFamily: MONO, fontSize: 9.5, fontWeight: 600, color: T.dim, transform: "translateY(4px)" }}>
            {days == null ? "—" : days + "י׳"}
          </span>
        </div>
      )}
    </div>
  );
}

/* ---------- 9b. רכיבי AI ואנימציה ---------- */

/* מספר שנספר כלפי מעלה */
function useCountUp(target, ms = 800) {
  const [v, setV] = useState(0);
  const ref = useRef(0);
  useEffect(() => {
    if (typeof window === "undefined" || !window.requestAnimationFrame) { setV(target); return; }
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) { setV(target); return; }
    const from = ref.current, delta = target - from, t0 = Date.now();
    let raf;
    const tick = () => {
      const t = Math.min(1, (Date.now() - t0) / ms);
      const e = 1 - Math.pow(1 - t, 3);
      const cur = from + delta * e;
      setV(cur);
      ref.current = cur;
      if (t < 1) raf = window.requestAnimationFrame(tick); else ref.current = target;
    };
    raf = window.requestAnimationFrame(tick);
    return () => window.cancelAnimationFrame && window.cancelAnimationFrame(raf);
  }, [target, ms]);
  return v;
}
function CountUp({ n, fmt, style }) {
  const v = useCountUp(n);
  return <span style={style}>{fmt ? fmt(v) : Math.round(v)}</span>;
}

/* ניצוץ AI — סימן אחיד לכל דבר שהמערכת פירשה ולא רק הציגה */
